import { useCallback, useEffect, useRef, useState } from 'react'
import { Card, CardContent } from '@/components/ui/card'
import { Input } from '@/components/ui/input'
import { useCartStore, type CustomerSelectorItem } from '../store'

// ============================================================================
// Types
// ============================================================================

interface CustomerSearchResponse {
  customers: CustomerSelectorItem[]
}

// ============================================================================
// Debounce hook — minimal inline implementation (250ms)
// ============================================================================

function useDebounce<T>(value: T, delayMs: number): T {
  const [debouncedValue, setDebouncedValue] = useState<T>(value)

  useEffect(() => {
    const timer = setTimeout(() => setDebouncedValue(value), delayMs)
    return () => clearTimeout(timer)
  }, [value, delayMs])

  return debouncedValue
}

// ============================================================================
// Component — Customer Selector (autocomplete input)
// ============================================================================

export function CustomerSelector() {
  const customerId = useCartStore((s) => s.customerId)
  const setCustomer = useCartStore((s) => s.setCustomer)

  // Search state
  const [query, setQuery] = useState('')
  const [results, setResults] = useState<CustomerSelectorItem[]>([])
  const [isLoading, setIsLoading] = useState(false)
  const [isOpen, setIsOpen] = useState(false)
  const [highlightIndex, setHighlightIndex] = useState(-1)

  // Cached selected customer (fetched on mount if customerId is set)
  const [selectedCustomerCache, setSelectedCustomerCache] = useState<CustomerSelectorItem | null>(null)

  // Debounced query (250ms delay before API call)
  const debouncedQuery = useDebounce(query, 250)

  // Refs for keyboard navigation and click-outside detection
  const inputRef = useRef<HTMLInputElement>(null)
  const dropdownRef = useRef<HTMLDivElement>(null)

  // ── Fetch selected customer on mount (if customerId is set) ──────

  useEffect(() => {
    if (!customerId) return

    let cancelled = false

    async function fetchSelectedCustomer() {
      try {
        const response = await fetch('/api/customers')
        if (response.ok) {
          const data: CustomerSearchResponse = await response.json()
          if (!cancelled) {
            const found = data.customers.find((c) => c.id === customerId)
            setSelectedCustomerCache(found ?? null)
          }
        }
      } catch {
        // Silently fail
      }
    }

    fetchSelectedCustomer()
    return () => { cancelled = true }
  }, [customerId])

  // ── Fetch customers on debounced query change ────────────────────

  useEffect(() => {
    // No search term → clear results, close dropdown
    if (!debouncedQuery || debouncedQuery.trim() === '') {
      setResults([])
      setIsOpen(false)
      return
    }

    let cancelled = false

    async function fetchCustomers() {
      setIsLoading(true)
      try {
        const response = await fetch(`/api/customers?search=${encodeURIComponent(debouncedQuery.trim())}`)
        if (response.ok) {
          const data: CustomerSearchResponse = await response.json()
          if (!cancelled) {
            setResults(data.customers.slice(0, 20))
            setIsOpen(true)
            setHighlightIndex(-1)
          }
        } else {
          if (!cancelled) {
            setResults([])
            setIsOpen(false)
          }
        }
      } catch {
        // Silently fail — walk-in is always available
        if (!cancelled) {
          setResults([])
          setIsOpen(false)
        }
      } finally {
        if (!cancelled) {
          setIsLoading(false)
        }
      }
    }

    fetchCustomers()
    return () => { cancelled = true }
  }, [debouncedQuery])

  // ── Click-outside handler — close dropdown when clicking outside ─

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (
        dropdownRef.current && !dropdownRef.current.contains(event.target as Node) &&
        inputRef.current && !inputRef.current.contains(event.target as Node)
      ) {
        setIsOpen(false)
      }
    }

    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [])

  // ── Select a customer ────────────────────────────────────────────

  const handleSelectCustomer = useCallback((id: string | null) => {
    setCustomer(id)
    setIsOpen(false)
    if (id === null) {
      // Reset to walk-in — clear input
      setQuery('')
      setResults([])
    }
  }, [setCustomer])

  // ── Keyboard navigation ──────────────────────────────────────────

  const handleKeyDown = useCallback((e: React.KeyboardEvent<HTMLInputElement>) => {
    if (!isOpen || results.length === 0) return

    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault()
        setHighlightIndex((prev) => Math.min(prev + 1, results.length - 1))
        break

      case 'ArrowUp':
        e.preventDefault()
        setHighlightIndex((prev) => Math.max(prev - 1, 0))
        break

      case 'Enter':
        e.preventDefault()
        if (highlightIndex >= 0 && highlightIndex < results.length) {
          handleSelectCustomer(results[highlightIndex].id)
        } else if (results.length === 1) {
          // Auto-select single result
          handleSelectCustomer(results[0].id)
        }
        break

      case 'Escape':
        e.preventDefault()
        setIsOpen(false)
        inputRef.current?.blur()
        break
    }
  }, [isOpen, results, highlightIndex, handleSelectCustomer])

  // ── Render helpers ───────────────────────────────────────────────

  // Prefer cached selected customer; fall back to searching in results
  const displaySelectedCustomer = selectedCustomerCache ?? results.find((c) => c.id === customerId) ?? null

  return (
    <Card>
      <CardContent className="p-4 space-y-3">
        {/* Label */}
        <label htmlFor="customer-search" className="text-sm font-medium text-muted-foreground">
          Customer
        </label>

        {/* Search input with dropdown */}
        <div ref={dropdownRef} className="relative">
          <Input
            id="customer-search"
            ref={inputRef}
            type="search"
            placeholder="Search customers..."
            value={query}
            onChange={(e) => {
              setQuery(e.target.value)
              setIsOpen(true)
              setHighlightIndex(-1)
            }}
            onFocus={() => {
              if (results.length > 0) setIsOpen(true)
            }}
            onKeyDown={handleKeyDown}
            className="w-full"
          />

          {/* Dropdown */}
          {isOpen && results.length > 0 && (
            <div className="absolute z-50 w-full mt-1 bg-popover border rounded-md shadow-lg max-h-64 overflow-y-auto">
              {/* Loading indicator */}
              {isLoading && (
                <div className="px-3 py-2 text-sm text-muted-foreground">Searching...</div>
              )}

              {/* Results list */}
              {!isLoading && results.map((customer, index) => (
                <button
                  key={customer.id}
                  type="button"
                  onClick={() => handleSelectCustomer(customer.id)}
                  onMouseEnter={() => setHighlightIndex(index)}
                  className={`w-full text-left px-3 py-2 text-sm transition-colors ${
                    index === highlightIndex
                      ? 'bg-accent text-accent-foreground'
                      : customerId === customer.id
                        ? 'bg-muted/50 font-medium'
                        : 'hover:bg-accent hover:text-accent-foreground'
                  }`}
                >
                  <div className="font-medium truncate">{customer.displayName}</div>
                  <div className="flex gap-3 text-xs text-muted-foreground mt-0.5">
                    {customer.email && (
                      <span className="truncate">{customer.email}</span>
                    )}
                    {customer.phone && (
                      <span className="truncate">{customer.phone}</span>
                    )}
                  </div>
                </button>
              ))}

              {/* No results within the loaded set */}
              {!isLoading && results.length === 0 && query.trim() !== '' && (
                <div className="px-3 py-2 text-sm text-muted-foreground">No customers found</div>
              )}
            </div>
          )}

          {/* Empty state hint — shown when input is focused but no results */}
          {isOpen && query.trim() !== '' && !isLoading && results.length === 0 && (
            <div className="absolute z-50 w-full mt-1 bg-popover border rounded-md shadow-lg px-3 py-2 text-sm text-muted-foreground">
              No customers found
            </div>
          )}
        </div>

        {/* Walk-in option — always visible */}
        <button
          type="button"
          onClick={() => handleSelectCustomer(null)}
          className={`w-full justify-start text-sm px-3 py-2 rounded-md border transition-colors ${
            customerId === null
              ? 'bg-primary text-primary-foreground border-transparent'
              : 'border-dashed border-input hover:bg-accent hover:text-accent-foreground'
          }`}
        >
          Walk-in (anonymous)
        </button>

        {/* Selected customer info */}
        {customerId !== null && displaySelectedCustomer && (
          <div className="pt-2 border-t text-xs text-muted-foreground space-y-0.5">
            <span className="font-medium">{displaySelectedCustomer.displayName}</span>
            {displaySelectedCustomer.email && <div>{displaySelectedCustomer.email}</div>}
            {displaySelectedCustomer.phone && <div>{displaySelectedCustomer.phone}</div>}
          </div>
        )}

        {/* Walk-in selected info */}
        {customerId === null && (
          <div className="pt-2 border-t text-xs text-muted-foreground italic">
            Anonymous sale — no customer attached
          </div>
        )}
      </CardContent>
    </Card>
  )
}

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'
import { render, screen, fireEvent, waitFor, act } from '@testing-library/react'
import { CustomerSelector } from '../CustomerSelector'
import { useCartStore } from '../../store'

// ── Mock fetch globally ────────────────────────────────────────────

function mockFetchCustomers(customers: Array<{ id: string; displayName: string; type: 'private' | 'company'; email?: string | null; phone?: string | null }>) {
  const mockFn = vi.fn().mockImplementation(async (url: string | URL | Request) => {
    const urlString = url.toString()
    if (urlString.includes('/api/customers')) {
      return {
        ok: true,
        json: async () => ({ customers }),
      } as Response
    }
    return { ok: false } as Response
  })
  vi.stubGlobal('fetch', mockFn)
}

function mockFetchError() {
  const mockFn = vi.fn().mockImplementation(async () => {
    return { ok: false } as Response
  })
  vi.stubGlobal('fetch', mockFn)
}

// ── Helper to reset store ──────────────────────────────────────────

function resetStore() {
  useCartStore.setState({
    lineItems: [],
    customerId: null,
    checkoutError: null,
    checkoutSuccess: null,
    isCheckingOut: false,
    subtotalNet: 0,
    vatTotal: 0,
    totalGross: 0,
    canCheckout: false,
  })
}

// ── Test data ──────────────────────────────────────────────────────

const mockCustomers = [
  { id: 'c1', displayName: 'Alice Smith', type: 'private' as const, email: 'alice@example.com', phone: '+32470123456' },
  { id: 'c2', displayName: 'Bob Jones', type: 'private' as const, email: 'bob@example.com', phone: null },
  { id: 'c3', displayName: 'Acme Corp', type: 'company' as const, email: 'info@acme.com', phone: '+3221234567' },
]

// ── Tests ──────────────────────────────────────────────────────────

describe('CustomerSelector', () => {
  beforeEach(() => {
    resetStore()
  })

  afterEach(() => {
    vi.restoreAllMocks()
  })

  it('renders with empty input and walk-in option on mount', () => {
    render(<CustomerSelector />)

    const input = screen.getByLabelText(/customer/i) as HTMLInputElement
    expect(input).toBeInTheDocument()
    expect(input.value).toBe('')

    // Walk-in button always visible
    expect(screen.getByText(/walk-in/i)).toBeInTheDocument()
  })

  it('shows no results until user types', () => {
    render(<CustomerSelector />)

    const dropdown = screen.queryByRole('listbox')
    expect(dropdown).not.toBeInTheDocument()
  })

  it('fetches customers after typing (debounced)', async () => {
    mockFetchCustomers(mockCustomers)
    render(<CustomerSelector />)

    const input = screen.getByLabelText(/customer/i) as HTMLInputElement

    // Type a character
    await act(async () => {
      fireEvent.change(input, { target: { value: 'alice' } })
    })

    // Should not have fetched yet (debounce delay)
    expect(fetch).not.toHaveBeenCalled()

    // Wait for debounce + fetch to complete
    await waitFor(() => {
      expect(fetch).toHaveBeenCalledWith(expect.stringContaining('/api/customers?search=alice'))
    }, { timeout: 500 })

    // Results should be visible
    await waitFor(() => {
      expect(screen.getByText('Alice Smith')).toBeInTheDocument()
    }, { timeout: 1000 })
  }, 10000)

  it('displays customer name, email, and phone in dropdown', async () => {
    mockFetchCustomers(mockCustomers)
    render(<CustomerSelector />)

    const input = screen.getByLabelText(/customer/i) as HTMLInputElement

    await act(async () => {
      fireEvent.change(input, { target: { value: 'a' } })
    })

    // Wait for debounce + fetch to complete
    await waitFor(() => {
      expect(fetch).toHaveBeenCalled()
    }, { timeout: 500 })

    // All three customers should appear (they all contain 'a')
    await waitFor(() => {
      expect(screen.getByText('Alice Smith')).toBeInTheDocument()
      expect(screen.getByText('Bob Jones')).toBeInTheDocument()
      expect(screen.getByText('Acme Corp')).toBeInTheDocument()
    }, { timeout: 1000 })

    // Email and phone visible for Alice
    await waitFor(() => {
      expect(screen.getByText('alice@example.com')).toBeInTheDocument()
      expect(screen.getByText('+32470123456')).toBeInTheDocument()
    }, { timeout: 1000 })

    // Bob has no phone, but email is shown
    expect(screen.getByText('bob@example.com')).toBeInTheDocument()
  }, 10000)

  it('selects a customer and updates the cart store', async () => {
    mockFetchCustomers(mockCustomers)
    render(<CustomerSelector />)

    const input = screen.getByLabelText(/customer/i) as HTMLInputElement

    await act(async () => {
      fireEvent.change(input, { target: { value: 'alice' } })
    })

    // Wait for debounce + fetch to complete
    await waitFor(() => {
      expect(screen.getByText('Alice Smith')).toBeInTheDocument()
    }, { timeout: 1000 })

    // Click on Alice Smith result
    await act(async () => {
      fireEvent.click(screen.getByText('Alice Smith'))
    })

    expect(useCartStore.getState().customerId).toBe('c1')
  }, 5000)

  it('selects walk-in and sets customerId to null', async () => {
    // Pre-select a customer first
    useCartStore.setState({ customerId: 'c1' })

    render(<CustomerSelector />)

    const walkInBtn = screen.getByText(/walk-in/i) as HTMLButtonElement

    await act(async () => {
      fireEvent.click(walkInBtn)
    })

    expect(useCartStore.getState().customerId).toBeNull()
  })

  it('closes dropdown on Escape key', async () => {
    mockFetchCustomers(mockCustomers)
    render(<CustomerSelector />)

    const input = screen.getByLabelText(/customer/i) as HTMLInputElement

    await act(async () => {
      fireEvent.change(input, { target: { value: 'a' } })
    })

    // Wait for debounce + fetch to complete
    await waitFor(() => {
      expect(screen.getByText('Alice Smith')).toBeInTheDocument()
    }, { timeout: 1000 })

    // Press Escape
    await act(async () => {
      fireEvent.keyDown(input, { key: 'Escape' })
    })

    // Dropdown should close (results hidden)
    await waitFor(() => {
      expect(screen.queryByText('Alice Smith')).not.toBeInTheDocument()
    }, { timeout: 1000 })
  }, 5000)

  it('highlights results with keyboard navigation', async () => {
    mockFetchCustomers(mockCustomers)
    render(<CustomerSelector />)

    const input = screen.getByLabelText(/customer/i) as HTMLInputElement

    await act(async () => {
      fireEvent.change(input, { target: { value: 'a' } })
    })

    // Wait for debounce + fetch to complete
    await waitFor(() => {
      expect(screen.getByText('Alice Smith')).toBeInTheDocument()
    }, { timeout: 1000 })

    // Navigate down (from -1 → 0, Alice highlighted)
    await act(async () => {
      fireEvent.keyDown(input, { key: 'ArrowDown' })
    })

    const aliceBtn = screen.getByText('Alice Smith').closest('button')
    expect(aliceBtn).toHaveClass('bg-accent')

    // Navigate down again (from 0 → 1, Bob highlighted)
    await act(async () => {
      fireEvent.keyDown(input, { key: 'ArrowDown' })
    })

    const bobBtn = screen.getByText('Bob Jones').closest('button')
    expect(bobBtn).toHaveClass('bg-accent')

    // Navigate up (from 1 → 0, Alice highlighted again)
    await act(async () => {
      fireEvent.keyDown(input, { key: 'ArrowUp' })
    })

    const aliceBtn2 = screen.getByText('Alice Smith').closest('button')
    expect(aliceBtn2).toHaveClass('bg-accent')
  }, 5000)

  it('selects customer with Enter key when highlighted', async () => {
    mockFetchCustomers(mockCustomers)
    render(<CustomerSelector />)

    const input = screen.getByLabelText(/customer/i) as HTMLInputElement

    await act(async () => {
      fireEvent.change(input, { target: { value: 'a' } })
    })

    // Wait for debounce + fetch to complete
    await waitFor(() => {
      expect(screen.getByText('Alice Smith')).toBeInTheDocument()
    }, { timeout: 1000 })

    // Navigate to Bob Jones (index 1)
    await act(async () => {
      fireEvent.keyDown(input, { key: 'ArrowDown' })
    })
    await act(async () => {
      fireEvent.keyDown(input, { key: 'ArrowDown' })
    })

    // Press Enter to select
    await act(async () => {
      fireEvent.keyDown(input, { key: 'Enter' })
    })

    expect(useCartStore.getState().customerId).toBe('c2')
  }, 5000)

  it('auto-selects when only one result matches', async () => {
    mockFetchCustomers([{ id: 'c1', displayName: 'Alice Smith', type: 'private' as const, email: 'alice@example.com', phone: null }])
    render(<CustomerSelector />)

    const input = screen.getByLabelText(/customer/i) as HTMLInputElement

    await act(async () => {
      fireEvent.change(input, { target: { value: 'alice' } })
    })

    // Wait for debounce + fetch to complete
    await waitFor(() => {
      expect(screen.getByText('Alice Smith')).toBeInTheDocument()
    }, { timeout: 1000 })

    // Single result should be auto-selected on Enter
    await act(async () => {
      fireEvent.keyDown(input, { key: 'Enter' })
    })

    expect(useCartStore.getState().customerId).toBe('c1')
  }, 5000)

  it('clears input when walk-in is selected', async () => {
    mockFetchCustomers(mockCustomers)
    render(<CustomerSelector />)

    const input = screen.getByLabelText(/customer/i) as HTMLInputElement

    // Type something to trigger search
    await act(async () => {
      fireEvent.change(input, { target: { value: 'alice' } })
    })

    // Wait for debounce + fetch to complete
    await waitFor(() => {
      expect(screen.getByText('Alice Smith')).toBeInTheDocument()
    }, { timeout: 1000 })

    // Click walk-in
    const walkInBtn = screen.getByText(/walk-in/i) as HTMLButtonElement
    await act(async () => {
      fireEvent.click(walkInBtn)
    })

    expect(input.value).toBe('')
  }, 5000)

  it('handles fetch errors gracefully', async () => {
    mockFetchError()
    render(<CustomerSelector />)

    const input = screen.getByLabelText(/customer/i) as HTMLInputElement

    await act(async () => {
      fireEvent.change(input, { target: { value: 'test' } })
    })

    // Wait for debounce + fetch to complete (should fail silently)
    await waitFor(() => {
      expect(fetch).toHaveBeenCalled()
    }, { timeout: 500 })

    // Should not crash — just show no results
    expect(useCartStore.getState().customerId).toBeNull()
  }, 5000)

  it('limits results to max 20', async () => {
    const manyCustomers = Array.from({ length: 30 }, (_, i) => ({
      id: `c${i}`,
      displayName: `Customer ${i}`,
      type: 'private' as const,
      email: `customer${i}@example.com`,
      phone: null,
    }))

    mockFetchCustomers(manyCustomers)
    render(<CustomerSelector />)

    const input = screen.getByLabelText(/customer/i) as HTMLInputElement

    await act(async () => {
      fireEvent.change(input, { target: { value: 'c' } })
    })

    // Wait for debounce + fetch to complete
    await waitFor(() => {
      expect(fetch).toHaveBeenCalled()
    }, { timeout: 500 })

    // Only 20 results should be visible (the backend limits to 20)
    const resultButtons = screen.getAllByRole('button', { name: /customer \d+/i })
    expect(resultButtons.length).toBe(20)
  }, 5000)

  it('shows selected customer info below the input', async () => {
    // Pre-select a customer
    useCartStore.setState({ customerId: 'c1' })

    mockFetchCustomers(mockCustomers)

    render(<CustomerSelector />)

    // Wait for any pending state updates to flush
    await act(async () => {})

    // Selected customer info should be visible (fetch is async, give it time)
    await waitFor(() => {
      expect(screen.getByText('Alice Smith')).toBeInTheDocument()
    }, { timeout: 5000 })
  })

  it('shows anonymous sale message when walk-in is selected', async () => {
    useCartStore.setState({ customerId: null })

    render(<CustomerSelector />)

    await waitFor(() => {
      expect(screen.getByText(/anonymous sale/i)).toBeInTheDocument()
    }, { timeout: 3000 })
  })
})

/**
 * Combobox — A generic searchable dropdown built on Radix Popover.
 *
 * Provides:
 * - Search input with debounce (managed by caller via `onSearchChange`)
 * - Floating results list with keyboard navigation
 * - Loading and empty states
 * - Selected item display with optional clear button
 *
 * Usage:
 * ```tsx
 * <Combobox<PostalCodeResult>
 *   items={results}
 *   isLoading={isLoading}
 *   value={selectedItem}
 *   onValueChange={(item) => setSelected(item)}
 *   onSearchChange={(query) => setSearch(query)}
 *   placeholder="Search..."
 *   renderOption={(item) => <span>{item.name}</span>}
 * />
 * ```
 */

import { useState, useRef, useEffect, useCallback } from 'react'
import { cn } from '@/shared/lib/utils.js'
import { X, Loader2 } from 'lucide-react'
import type { ComponentPropsWithoutRef, KeyboardEvent as ReactKeyboardEvent } from 'react'

// ---------------------------------------------------------------------------
// Props
// ---------------------------------------------------------------------------

export interface ComboboxProps<T> extends Omit<ComponentPropsWithoutRef<'div'>, 'onValueChange'> {
  /** Available items to display in the dropdown. */
  items: T[]
  /** Whether a search is currently in progress. */
  isLoading: boolean
  /** Currently selected item (null = unselected). */
  value: T | null
  /** Called when user selects an item. Pass null to clear selection. */
  onValueChange: (value: T | null) => void
  /** Called with the current search query string as user types. */
  onSearchChange: (query: string) => void
  /** Placeholder text for the input field. */
  placeholder?: string
  /** Render function for each dropdown item. Receives the full item object. */
  renderOption: (item: T, index: number) => React.ReactNode
  /** Whether the combobox is disabled. Shows a read-only label when true and has a value. */
  disabled?: boolean
}

// ---------------------------------------------------------------------------
// Component — Combobox
// ---------------------------------------------------------------------------

export function Combobox<T extends { [key: string]: unknown }>({
  items,
  isLoading,
  value,
  onValueChange,
  onSearchChange,
  placeholder = 'Search...',
  renderOption,
  disabled = false,
  className,
}: ComboboxProps<T>) {
  const [isOpen, setIsOpen] = useState(false)
  const [highlightedIndex, setHighlightedIndex] = useState(-1)

  // Local search query state — drives the input value directly.
  // onSearchChange is called as a side-effect for parent integration.
  const [searchQuery, setSearchQuery] = useState('')

  // Local controlled input — synced with value state.
  // When a selection is made, the display shows it and the input area becomes read-only.
  // When cleared, we reset to search mode.
  const [displayValue, setDisplayValue] = useState<string>('')

  // Keep displayValue in sync with external value prop.
  useEffect(() => {
    if (value) {
      setDisplayValue(String(value.name))
    } else {
      setDisplayValue('')
    }
  }, [value])

  // Refs for focus management and click-outside detection.
  const containerRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)
  const listRef = useRef<HTMLUListElement>(null)

  // Reset highlight when items change (new search results).
  useEffect(() => {
    setHighlightedIndex(-1)
  }, [items])

  /** Close the dropdown. */
  const close = useCallback(() => {
    setIsOpen(false)
    setHighlightedIndex(-1)
  }, [])

  /** Open the dropdown and focus the input. */
  const open = useCallback(() => {
    if (!disabled) {
      setIsOpen(true)
      // If we have a value, select it all so user can type over immediately.
      setTimeout(() => {
        inputRef.current?.focus()
        if (displayValue && isOpen) {
          inputRef.current?.select()
        }
      }, 0)
    }
  }, [disabled, displayValue, isOpen])

  /** Handle selecting an item. */
  const handleSelect = useCallback((item: T) => {
    onValueChange(item)
    close()
  }, [onValueChange, close])

  /** Clear selection and reopen for a new search. */
  const handleClear = useCallback((e: React.MouseEvent) => {
    e.stopPropagation()
    setSearchQuery('')
    onValueChange(null)
    close()
    // Reopen so user can immediately type again.
    setTimeout(() => inputRef.current?.focus(), 0)
  }, [onValueChange, close])

  /** Handle keyboard navigation in the dropdown. */
  const handleKeyDown = useCallback((e: ReactKeyboardEvent<HTMLInputElement>) => {
    if (!isOpen) return

    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault()
        setHighlightedIndex((prev) => Math.min(prev + 1, items.length - 1))
        break

      case 'ArrowUp':
        e.preventDefault()
        setHighlightedIndex((prev) => Math.max(prev - 1, 0))
        break

      case 'Enter': {
        e.preventDefault()
        if (highlightedIndex >= 0 && highlightedIndex < items.length) {
          handleSelect(items[highlightedIndex])
        } else if (!value && items.length > 0) {
          // Select first item when nothing is selected and there are results.
          handleSelect(items[0])
        }
        break
      }

      case 'Escape':
        e.preventDefault()
        close()
        break

      default:
        break
    }
  }, [isOpen, highlightedIndex, items.length, value, handleSelect, close])

  /** Handle input blur — close dropdown if focus leaves the container. */
  const handleBlur = useCallback((e: React.FocusEvent<HTMLInputElement>) => {
    // Check if focus is moving to a descendant (the results list).
    const relatedTarget = e.relatedTarget as HTMLElement | null
    if (relatedTarget?.closest('[data-combobox-list]')) return
    close()
  }, [close])

  // Scroll highlighted item into view.
  useEffect(() => {
    if (highlightedIndex >= 0 && listRef.current) {
      const el = listRef.current.children[highlightedIndex] as HTMLElement | null
      el?.scrollIntoView({ block: 'nearest' })
    }
  }, [highlightedIndex])

  // -----------------------------------------------------------------------
  // Render — selected display (when not editing) or input (when open/searching)
  // -----------------------------------------------------------------------

  const hasValue = value !== null && displayValue.length > 0

  if (disabled && hasValue) {
    return (
      <div className={cn('text-sm text-muted-foreground', className)}>
        {displayValue}
      </div>
    )
  }

  return (
    <div ref={containerRef} className={cn(className)}>
      {/* Input wrapper */}
      <div
        role="combobox"
        aria-expanded={isOpen}
        aria-haspopup="listbox"
        onClick={open}
        className={cn(
          'flex h-10 w-full items-center gap-2 rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background focus-within:outline-none focus-within:ring-2 focus-within:ring-ring focus-within:ring-offset-2 cursor-text',
        )}
      >
        {/* Selected value display or search input */}
        {hasValue ? (
          <div className="flex flex-1 items-center gap-1.5">
            <span>{displayValue}</span>
            {!disabled && (
              <button
                type="button"
                onClick={handleClear}
                className="ml-auto p-0.5 rounded-full hover:bg-muted text-muted-foreground hover:text-foreground transition-colors"
                tabIndex={-1}
              >
                <X className="h-3 w-3" />
                <span className="sr-only">Clear selection</span>
              </button>
            )}
          </div>
        ) : (
          <input
            ref={inputRef}
            type="text"
            value={searchQuery}
            onChange={(e) => {
              setSearchQuery(e.target.value)
              onSearchChange(e.target.value)
            }}
            onKeyDown={handleKeyDown}
            onBlur={handleBlur}
            placeholder={placeholder}
            className="flex-1 bg-transparent outline-none text-sm placeholder:text-muted-foreground disabled:cursor-not-allowed"
            disabled={disabled}
          />
        )}

        {/* Loading indicator */}
        {isLoading && (
          <Loader2 className="h-4 w-4 animate-spin text-muted-foreground shrink-0" />
        )}
      </div>

      {/* Dropdown results */}
      {isOpen && !disabled && (
        <ul
          ref={listRef}
          data-combobox-list
          role="listbox"
          className="absolute z-50 mt-1 max-h-64 w-full overflow-y-auto rounded-md border bg-popover text-popover-foreground shadow-lg outline-none"
        >
          {isLoading && items.length === 0 ? (
            <li className="flex items-center gap-2 px-3 py-2 text-sm text-muted-foreground">
              <Loader2 className="h-4 w-4 animate-spin" />
              Searching...
            </li>
          ) : items.length === 0 ? (
            <li className="px-3 py-2 text-sm text-muted-foreground">No results</li>
          ) : (
            items.map((item, index) => (
              <li
                key={String(item.code ?? item.name)} // Use unique identifier if available.
                role="option"
                aria-selected={index === highlightedIndex}
                onMouseDown={(e) => {
                  e.preventDefault() // Prevent focus from leaving input (which triggers blur/close before React processes click)
                  handleSelect(item)
                }}
                className={cn(
                  'px-3 py-2 text-sm cursor-pointer transition-colors',
                  index === highlightedIndex && 'bg-accent text-accent-foreground'
                )}
              >
                {renderOption(item, index)}
              </li>
            ))
          )}
        </ul>
      )}
    </div>
  )
}
